function tradeFits(items,meta,target){
  const x=target%8,y=Math.floor(target/8);
  if(x+meta.width>8||y+meta.height>4)return false;
  return !items.some(i=>{
    if(i.slot===target)return false;
    const m=assets.catalog[i.index],ix=i.slot%8,iy=Math.floor(i.slot/8);
    return m&&x<ix+m.width&&x+meta.width>ix&&y<iy+m.height&&y+meta.height>iy;
  });
}
